CREATE TABLE upload_sessions(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),actor_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,expected_hash TEXT NOT NULL,kind TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),received INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'UPLOADING',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,result_id TEXT);
CREATE TABLE upload_chunks(upload_id TEXT NOT NULL REFERENCES upload_sessions(id),offset INTEGER NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(upload_id,offset));
CREATE TABLE document_versions(document_id TEXT NOT NULL REFERENCES documents(id),version INTEGER NOT NULL,object_key TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,mime TEXT NOT NULL,name TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),uploaded_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,reason TEXT NOT NULL,scan_state TEXT NOT NULL,PRIMARY KEY(document_id,version));
CREATE TRIGGER document_version_no_update BEFORE UPDATE ON document_versions BEGIN SELECT RAISE(ABORT,'immutable document version'); END;
CREATE TRIGGER document_version_no_delete BEFORE DELETE ON document_versions BEGIN SELECT RAISE(ABORT,'immutable document version'); END;
CREATE TABLE imaging_studies(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),study_uid TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),version INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(patient_id,study_uid));
CREATE TABLE imaging_series(id TEXT PRIMARY KEY,study_id TEXT NOT NULL REFERENCES imaging_studies(id),series_uid TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),UNIQUE(study_id,series_uid));
CREATE TABLE imaging_instances(id TEXT PRIMARY KEY,series_id TEXT NOT NULL REFERENCES imaging_series(id),sop_uid TEXT NOT NULL,object_key TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,mime TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),created_at INTEGER NOT NULL,UNIQUE(series_id,sop_uid));
CREATE TABLE imaging_revisions(study_id TEXT NOT NULL REFERENCES imaging_studies(id),version INTEGER NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),actor_id TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(study_id,version));
CREATE TABLE appointment_entries(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),body TEXT NOT NULL CHECK(json_valid(body)),version INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE appointment_versions(id TEXT NOT NULL,version INTEGER NOT NULL,body TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(id,version));
CREATE INDEX upload_owner ON upload_sessions(patient_id,status);
CREATE INDEX imaging_owner ON imaging_studies(patient_id,created_at);
